"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { BookOpenIcon, ChatCircleIcon, ClockCounterClockwiseIcon, QuestionIcon } from "@phosphor-icons/react/dist/ssr"

import { cn } from "@/lib/utils"

const TABS = [
  { href: "/templates/help-center", label: "물어보기", icon: ChatCircleIcon },
  { href: "/templates/help-center/manual", label: "매뉴얼 색인", icon: BookOpenIcon },
  { href: "/templates/help-center/faq", label: "FAQ", icon: QuestionIcon },
  { href: "/templates/help-center/history", label: "질문 이력", icon: ClockCounterClockwiseIcon },
] as const

/**
 * 도움말 센터 4탭 내비게이션(#100) — 라우트 전환이라 딥링크가 가능하다.
 * Radix Tabs(클라이언트 상태) 대신 app/templates/saas/_components/template-nav.tsx 와
 * 같은 Link 탭 패턴을 쓴다 — 이슈 설계("탭 전환이 라우트가 되도록")가 요구하는 지점.
 */
export function HelpCenterNav() {
  const pathname = usePathname()

  return (
    <nav
      aria-label="도움말 센터 탭"
      className="flex w-fit items-center gap-1 overflow-x-auto rounded-lg border border-border bg-card p-1"
    >
      {TABS.map((tab) => {
        const active = pathname === tab.href
        const Icon = tab.icon
        return (
          <Link
            key={tab.href}
            href={tab.href}
            aria-current={active ? "page" : undefined}
            className={cn(
              "flex shrink-0 items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
              active
                ? "bg-primary text-primary-foreground"
                : "text-muted-foreground hover:bg-muted hover:text-foreground",
            )}
          >
            <Icon size={16} weight={active ? "duotone" : "regular"} aria-hidden />
            {tab.label}
          </Link>
        )
      })}
    </nav>
  )
}

"use client"

import * as React from "react"
import { CheckCircleIcon, ClockIcon, PaperPlaneRightIcon, SparkleIcon } from "@phosphor-icons/react/dist/ssr"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

import { QUESTION_HISTORY, type QuestionStatus } from "../_data/questions"
import { SUGGESTED_QUESTIONS } from "../_data/suggested-questions"

const STATUS_LABEL: Record<QuestionStatus, string> = {
  answered: "답변 완료",
  pending: "답변 대기",
}

const STATUS_CLASS: Record<QuestionStatus, string> = {
  answered: "border-success/40 bg-success/10 text-success",
  pending: "border-warning/40 bg-warning/10 text-warning",
}

const RECENT_ANSWERED = QUESTION_HISTORY.filter((q) => q.status === "answered").slice(0, 2)

/**
 * 물어보기 탭(#100) — 자유 질문 입력 + 추천 질문 칩 + 최근 답변 미리보기.
 *
 * ChatWidget(components/chat-widget.tsx)은 화면 구석 상주형 런처+패널이라 항상
 * 열려 있어야 하는 탭 본문으로 끼워 넣기에 맞지 않는다(설계 판단 — 최종 보고 참고).
 * 대신 같은 자유 질문 진입점 의도를 로컬 프레젠테이션 컴포넌트로 구현하고,
 * 새 카탈로그 컴포넌트는 만들지 않는다.
 */
export function AskPanel() {
  const [value, setValue] = React.useState("")
  const [submitted, setSubmitted] = React.useState<string[]>([])

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    const question = value.trim()
    if (!question) return
    setSubmitted((prev) => [question, ...prev])
    setValue("")
  }

  return (
    <div className="flex flex-col gap-6">
      <form onSubmit={handleSubmit} className="flex flex-col gap-3 rounded-lg border border-border bg-card p-4">
        <label htmlFor="ask-question" className="text-sm font-medium text-foreground">
          무엇이 궁금하신가요?
        </label>
        <Textarea
          id="ask-question"
          value={value}
          onChange={(event) => setValue(event.target.value)}
          placeholder="예: 여신 심사 화면에서 반려 사유는 어디서 확인하나요?"
          rows={3}
          className="resize-none"
        />

        <div className="flex flex-wrap gap-1.5">
          {SUGGESTED_QUESTIONS.map((question) => (
            <button
              key={question}
              type="button"
              onClick={() => setValue(question)}
              className="flex items-center gap-1 rounded-full border border-border bg-background px-2.5 py-1 text-xs text-muted-foreground transition-colors hover:border-primary/40 hover:text-foreground"
            >
              <SparkleIcon size={12} aria-hidden />
              {question}
            </button>
          ))}
        </div>

        <div className="flex justify-end">
          <Button type="submit" disabled={!value.trim()}>
            <PaperPlaneRightIcon aria-hidden />
            질문 보내기
          </Button>
        </div>
      </form>

      {submitted.length > 0 ? (
        <section aria-label="방금 보낸 질문" className="flex flex-col gap-2">
          <h3 className="text-sm font-semibold text-foreground">방금 보낸 질문</h3>
          <ul className="flex flex-col gap-2">
            {submitted.map((question) => (
              <li
                key={question}
                className="flex items-center gap-2 rounded-lg border border-dashed border-border bg-muted/30 px-3 py-2 text-sm text-foreground"
              >
                <ClockIcon size={14} className="shrink-0 text-muted-foreground" aria-hidden />
                {question}
                <Badge variant="outline" className={cn("ml-auto shrink-0 gap-1", STATUS_CLASS.pending)}>
                  {STATUS_LABEL.pending}
                </Badge>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <section aria-label="최근 답변된 질문" className="flex flex-col gap-2">
        <h3 className="text-sm font-semibold text-foreground">최근 답변된 질문</h3>
        <ul className="flex flex-col gap-2">
          {RECENT_ANSWERED.map((item) => (
            <li key={item.id} className="flex flex-col gap-1 rounded-lg border border-border bg-card p-3">
              <div className="flex items-center gap-2">
                <CheckCircleIcon size={14} weight="fill" className="shrink-0 text-success" aria-hidden />
                <p className="text-sm font-medium text-foreground">{item.question}</p>
                <Badge variant="outline" className={cn("ml-auto shrink-0 gap-1", STATUS_CLASS.answered)}>
                  {STATUS_LABEL.answered}
                </Badge>
              </div>
              {item.answer ? <p className="pl-6 text-sm text-muted-foreground">{item.answer}</p> : null}
            </li>
          ))}
        </ul>
      </section>
    </div>
  )
}

"use client"

import * as React from "react"
import { FileTextIcon } from "@phosphor-icons/react/dist/ssr"

import { Badge } from "@/components/ui/badge"
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command"

import { MANUAL_CATEGORIES, type ManualEntry } from "../_data/manual"

const FIRST_ENTRY = MANUAL_CATEGORIES[0]?.entries[0] ?? null

/**
 * 매뉴얼 색인 탭(#100) — components/ui/command.tsx 의 Command(다이얼로그 아님,
 * 인라인)를 화면·기능 트리 검색기로 재사용한다. 좌측에서 고른 항목이 우측
 * 디테일 패널에 뜬다(md 미만에서는 세로로 쌓인다).
 */
export function ManualIndex() {
  const [selected, setSelected] = React.useState<ManualEntry | null>(FIRST_ENTRY)

  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-[280px_1fr]">
      <Command className="min-w-0 rounded-lg border border-border" aria-label="매뉴얼 검색">
        <CommandInput placeholder="화면·기능 검색…" />
        <CommandList>
          <CommandEmpty>일치하는 매뉴얼이 없습니다.</CommandEmpty>
          {MANUAL_CATEGORIES.map((category) => (
            <CommandGroup key={category.id} heading={category.label}>
              {category.entries.map((entry) => (
                <CommandItem key={entry.id} value={`${category.label} ${entry.title}`} onSelect={() => setSelected(entry)}>
                  <FileTextIcon aria-hidden />
                  {entry.title}
                </CommandItem>
              ))}
            </CommandGroup>
          ))}
        </CommandList>
      </Command>

      <div className="min-w-0 rounded-lg border border-border bg-card p-4">
        {selected ? (
          <div className="flex flex-col gap-2">
            <Badge variant="secondary" className="w-fit">
              {selected.screen}
            </Badge>
            <h3 className="text-base font-semibold text-foreground">{selected.title}</h3>
            <p className="text-sm leading-relaxed text-muted-foreground">{selected.body}</p>
          </div>
        ) : (
          <p className="text-sm text-muted-foreground">왼쪽에서 항목을 선택하면 설명이 여기 표시됩니다.</p>
        )}
      </div>
    </div>
  )
}

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion"
import { Badge } from "@/components/ui/badge"

import { FAQ_ITEMS } from "../_data/faq"

const CATEGORIES = [...new Set(FAQ_ITEMS.map((item) => item.category))]

/** FAQ 탭(#100) — components/ui/accordion.tsx 를 카테고리별로 그룹핑해 조합한다. */
export function FaqList() {
  return (
    <div className="flex flex-col gap-6">
      {CATEGORIES.map((category) => {
        const items = FAQ_ITEMS.filter((item) => item.category === category)
        return (
          <section key={category} aria-label={category} className="flex flex-col gap-2">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-foreground">
              {category}
              <Badge variant="outline" className="font-mono text-[10px] font-normal">
                {items.length}
              </Badge>
            </h3>
            <Accordion type="single" collapsible className="rounded-lg border border-border">
              {items.map((item) => (
                <AccordionItem key={item.id} value={item.id}>
                  <AccordionTrigger className="px-4">{item.question}</AccordionTrigger>
                  <AccordionContent className="px-4 text-muted-foreground">{item.answer}</AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          </section>
        )
      })}
    </div>
  )
}

import { CheckCircleIcon, ClockIcon } from "@phosphor-icons/react/dist/ssr"

import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"

import { QUESTION_HISTORY, type QuestionStatus } from "../_data/questions"

const STATUS_LABEL: Record<QuestionStatus, string> = {
  answered: "답변 완료",
  pending: "답변 대기",
}

const STATUS_CLASS: Record<QuestionStatus, string> = {
  answered: "border-success/40 bg-success/10 text-success",
  pending: "border-warning/40 bg-warning/10 text-warning",
}

/**
 * 질문 이력 탭(#100) — 표가 아니라 시간순 목록(이슈 설계). 상태는 배지 색뿐
 * 아니라 텍스트("답변 완료"/"답변 대기")와 아이콘으로도 구분한다(색 외 2번째
 * 채널). askedAt 은 목 데이터의 포맷된 문자열을 그대로 쓰고 new Date() 로
 * 내부에서 다시 계산하지 않는다(hydration).
 */
export function QuestionHistory() {
  return (
    <ol aria-label="내 질문 이력" className="relative flex flex-col gap-4 pl-2">
      {QUESTION_HISTORY.map((item) => {
        const Icon = item.status === "answered" ? CheckCircleIcon : ClockIcon
        return (
          <li key={item.id} className="relative flex gap-3 pb-4 pl-6 last:pb-0">
            <span aria-hidden className="absolute top-6 bottom-0 left-[7px] w-px bg-border last:hidden" />
            <span
              className={cn(
                "absolute top-1 left-0 flex size-4 shrink-0 items-center justify-center rounded-full border",
                STATUS_CLASS[item.status],
              )}
            >
              <Icon size={10} weight="fill" aria-hidden />
            </span>
            <div className="flex min-w-0 flex-1 flex-col gap-1 rounded-lg border border-border bg-card p-3">
              <div className="flex flex-wrap items-center gap-2">
                <span className="font-mono text-[11px] text-muted-foreground">{item.askedAt}</span>
                <Badge variant="outline" className={cn("gap-1 text-[10px]", STATUS_CLASS[item.status])}>
                  {STATUS_LABEL[item.status]}
                </Badge>
              </div>
              <p className="text-sm font-medium text-foreground">{item.question}</p>
              {item.answer ? <p className="text-sm text-muted-foreground">{item.answer}</p> : null}
            </div>
          </li>
        )
      })}
    </ol>
  )
}

